function solve(arr, p, q) {
  function findPath(i, target, path) {
    if (i >= arr.length || arr[i] === null || arr[i] === undefined) return null;
    const next = [...path, arr[i]];
    if (arr[i] === target) return next;
    return findPath(2 * i + 1, target, next) || findPath(2 * i + 2, target, next);
  }
  const P = findPath(0, p, []), Q = findPath(0, q, []);
  let lca = null;
  for (let i = 0; i < Math.min(P.length, Q.length); i++) {
    if (P[i] === Q[i]) lca = P[i];
    else break;
  }
  return lca;
}

function solve(arr, p, q) {
  function lca(i) {
    if (i >= arr.length || arr[i] === null || arr[i] === undefined) return null;
    if (arr[i] === p || arr[i] === q) return arr[i];
    const l = lca(2 * i + 1), r = lca(2 * i + 2);
    if (l !== null && r !== null) return arr[i];
    return l !== null ? l : r;
  }
  return lca(0);
}

